use vstd::prelude::*;

verus! {

    // to_lowercase: every uppercase ASCII letter in str1 is
    // converted to its lowercase counterpart; all other chars
    // are left unchanged.
    fn to_lowercase(str1: &Vec<char>) -> Vec<char>
        ensures
            // (1) the output has the same length as the input
            result.len() == str1.len(),
            // (2) element‐wise specification:
            //     for each index i, if str1[i] is 'A'..='Z',
            //     then result[i] == ((str1[i] as u8)+32) as char,
            //     otherwise result[i] == str1[i].
            forall |i: int|
                0 <= i && i < str1.len() ==>
                    if 'A' <= str1[i] && str1[i] <= 'Z' {
                        result[i] == ((str1[i] as u8) + 32) as char
                    } else {
                        result[i] == str1[i]
                    },
    {
        // Preallocate a new Vec<char> with the same capacity
        let mut result = Vec::with_capacity(str1.len());

        // Iterate over each character:
        for &c in str1.iter()
            // Loop‐invariants and a decreases‐measure to prove termination:
            invariant
                // we never push more than str1.len() characters
                result.len() <= str1.len(),
                // for each j < result.len(), result[j] already satisfies
                // the same element‐wise property we want at the end
                forall |j: int|
                    0 <= j && j < result.len() ==>
                        if 'A' <= str1[j] && str1[j] <= 'Z' {
                            result[j] == ((str1[j] as u8) + 32) as char
                        } else {
                            result[j] == str1[j]
                        },
            decreases str1.len() - result.len(),
        {
            if ('A'..='Z').contains(&c) {
                // Convert uppercase→lowercase by ASCII offset 32
                let lower = ((c as u8) + 32) as char;
                result.push(lower);
            } else {
                // leave all other characters unchanged
                result.push(c);
            }
        }

        result
    }

    fn main() {
        let input: Vec<char> = "Hello, WORLD! 123".chars().collect();
        let output = to_lowercase(&input);
        let output_string: String = output.into_iter().collect();
        assert_eq!(output_string, "hello, world! 123");
        println!("{}", output_string);
    }
}